insert into public.ic3_arcade_questions(id,lesson,prompt,choices,solution,explanation)
values
('guide-1-0-meaning',1,'Trong bài học, câu nào giải thích phù hợp nhất về “CPU thực thi lệnh”?',ARRAY['Khi bảng tính cộng 35 ô, CPU thực hiện các thao tác tính toán. Xung nhịp chỉ là một trong nhiều yếu tố ảnh hưởng tốc độ.','Dữ liệu tạm của bảng tính đang mở cần RAM. Mở thêm ứng dụng có thể làm bộ nhớ khả dụng giảm.','SSD dùng bộ nhớ flash, HDD dùng đĩa từ quay. Cả hai có thể giữ tệp sau khi tắt máy.']::text[],'Khi bảng tính cộng 35 ô, CPU thực hiện các thao tác tính toán. Xung nhịp chỉ là một trong nhiều yếu tố ảnh hưởng tốc độ.','CPU thực thi lệnh: Khi bảng tính cộng 35 ô, CPU thực hiện các thao tác tính toán. Xung nhịp chỉ là một trong nhiều yếu tố ảnh hưởng tốc độ.'),
('guide-1-0-concept',1,'Theo bài học, mô tả “Khi bảng tính cộng 35 ô, CPU thực hiện các thao tác tính toán. Xung nhịp chỉ là một trong nhiều yếu tố ảnh hưởng tốc độ.” liên quan trực tiếp nhất đến khái niệm nào?',ARRAY['CPU thực thi lệnh','RAM giữ phiên làm việc','Ổ lưu trữ giữ bản đã lưu']::text[],'CPU thực thi lệnh','Khi bảng tính cộng 35 ô, CPU thực hiện các thao tác tính toán. Xung nhịp chỉ là một trong nhiều yếu tố ảnh hưởng tốc độ.'),
('guide-1-1-meaning',1,'Trong bài học, câu nào giải thích phù hợp nhất về “RAM giữ phiên làm việc”?',ARRAY['Dữ liệu tạm của bảng tính đang mở cần RAM. Mở thêm ứng dụng có thể làm bộ nhớ khả dụng giảm.','Khi bảng tính cộng 35 ô, CPU thực hiện các thao tác tính toán. Xung nhịp chỉ là một trong nhiều yếu tố ảnh hưởng tốc độ.','SSD dùng bộ nhớ flash, HDD dùng đĩa từ quay. Cả hai có thể giữ tệp sau khi tắt máy.']::text[],'Dữ liệu tạm của bảng tính đang mở cần RAM. Mở thêm ứng dụng có thể làm bộ nhớ khả dụng giảm.','RAM giữ phiên làm việc: Dữ liệu tạm của bảng tính đang mở cần RAM. Mở thêm ứng dụng có thể làm bộ nhớ khả dụng giảm.'),
('guide-1-1-concept',1,'Theo bài học, mô tả “Dữ liệu tạm của bảng tính đang mở cần RAM. Mở thêm ứng dụng có thể làm bộ nhớ khả dụng giảm.” liên quan trực tiếp nhất đến khái niệm nào?',ARRAY['RAM giữ phiên làm việc','CPU thực thi lệnh','Ổ lưu trữ giữ bản đã lưu']::text[],'RAM giữ phiên làm việc','Dữ liệu tạm của bảng tính đang mở cần RAM. Mở thêm ứng dụng có thể làm bộ nhớ khả dụng giảm.'),
('guide-1-2-meaning',1,'Trong bài học, câu nào giải thích phù hợp nhất về “Ổ lưu trữ giữ bản đã lưu”?',ARRAY['SSD dùng bộ nhớ flash, HDD dùng đĩa từ quay. Cả hai có thể giữ tệp sau khi tắt máy.','Khi bảng tính cộng 35 ô, CPU thực hiện các thao tác tính toán. Xung nhịp chỉ là một trong nhiều yếu tố ảnh hưởng tốc độ.','Dữ liệu tạm của bảng tính đang mở cần RAM. Mở thêm ứng dụng có thể làm bộ nhớ khả dụng giảm.']::text[],'SSD dùng bộ nhớ flash, HDD dùng đĩa từ quay. Cả hai có thể giữ tệp sau khi tắt máy.','Ổ lưu trữ giữ bản đã lưu: SSD dùng bộ nhớ flash, HDD dùng đĩa từ quay. Cả hai có thể giữ tệp sau khi tắt máy.'),
('guide-1-2-concept',1,'Theo bài học, mô tả “SSD dùng bộ nhớ flash, HDD dùng đĩa từ quay. Cả hai có thể giữ tệp sau khi tắt máy.” liên quan trực tiếp nhất đến khái niệm nào?',ARRAY['Ổ lưu trữ giữ bản đã lưu','CPU thực thi lệnh','RAM giữ phiên làm việc']::text[],'Ổ lưu trữ giữ bản đã lưu','SSD dùng bộ nhớ flash, HDD dùng đĩa từ quay. Cả hai có thể giữ tệp sau khi tắt máy.'),
('guide-2-0-meaning',2,'Trong bài học, câu nào giải thích phù hợp nhất về “Nhập dữ liệu”?',ARRAY['Bàn phím nhận ký tự, micrô thu âm, webcam thu hình. Xét chiều thông tin từ người dùng vào máy.','Máy chiếu đưa ảnh lên màn chiếu. Loa biến dữ liệu âm thanh thành tiếng người nghe được.','HDMI có thể mang hình và tiếng. USB nối nhiều loại thiết bị. Đầu cắm và cổng cần tương thích.']::text[],'Bàn phím nhận ký tự, micrô thu âm, webcam thu hình. Xét chiều thông tin từ người dùng vào máy.','Nhập dữ liệu: Bàn phím nhận ký tự, micrô thu âm, webcam thu hình. Xét chiều thông tin từ người dùng vào máy.'),
('guide-2-0-concept',2,'Theo bài học, mô tả “Bàn phím nhận ký tự, micrô thu âm, webcam thu hình. Xét chiều thông tin từ người dùng vào máy.” liên quan trực tiếp nhất đến khái niệm nào?',ARRAY['Nhập dữ liệu','Xuất kết quả','Ghép đúng cổng']::text[],'Nhập dữ liệu','Bàn phím nhận ký tự, micrô thu âm, webcam thu hình. Xét chiều thông tin từ người dùng vào máy.'),
('guide-2-1-meaning',2,'Trong bài học, câu nào giải thích phù hợp nhất về “Xuất kết quả”?',ARRAY['Máy chiếu đưa ảnh lên màn chiếu. Loa biến dữ liệu âm thanh thành tiếng người nghe được.','Bàn phím nhận ký tự, micrô thu âm, webcam thu hình. Xét chiều thông tin từ người dùng vào máy.','HDMI có thể mang hình và tiếng. USB nối nhiều loại thiết bị. Đầu cắm và cổng cần tương thích.']::text[],'Máy chiếu đưa ảnh lên màn chiếu. Loa biến dữ liệu âm thanh thành tiếng người nghe được.','Xuất kết quả: Máy chiếu đưa ảnh lên màn chiếu. Loa biến dữ liệu âm thanh thành tiếng người nghe được.'),
('guide-2-1-concept',2,'Theo bài học, mô tả “Máy chiếu đưa ảnh lên màn chiếu. Loa biến dữ liệu âm thanh thành tiếng người nghe được.” liên quan trực tiếp nhất đến khái niệm nào?',ARRAY['Xuất kết quả','Nhập dữ liệu','Ghép đúng cổng']::text[],'Xuất kết quả','Máy chiếu đưa ảnh lên màn chiếu. Loa biến dữ liệu âm thanh thành tiếng người nghe được.'),
('guide-2-2-meaning',2,'Trong bài học, câu nào giải thích phù hợp nhất về “Ghép đúng cổng”?',ARRAY['HDMI có thể mang hình và tiếng. USB nối nhiều loại thiết bị. Đầu cắm và cổng cần tương thích.','Bàn phím nhận ký tự, micrô thu âm, webcam thu hình. Xét chiều thông tin từ người dùng vào máy.','Máy chiếu đưa ảnh lên màn chiếu. Loa biến dữ liệu âm thanh thành tiếng người nghe được.']::text[],'HDMI có thể mang hình và tiếng. USB nối nhiều loại thiết bị. Đầu cắm và cổng cần tương thích.','Ghép đúng cổng: HDMI có thể mang hình và tiếng. USB nối nhiều loại thiết bị. Đầu cắm và cổng cần tương thích.'),
('guide-2-2-concept',2,'Theo bài học, mô tả “HDMI có thể mang hình và tiếng. USB nối nhiều loại thiết bị. Đầu cắm và cổng cần tương thích.” liên quan trực tiếp nhất đến khái niệm nào?',ARRAY['Ghép đúng cổng','Nhập dữ liệu','Xuất kết quả']::text[],'Ghép đúng cổng','HDMI có thể mang hình và tiếng. USB nối nhiều loại thiết bị. Đầu cắm và cổng cần tương thích.'),
('guide-3-0-meaning',3,'Trong bài học, câu nào giải thích phù hợp nhất về “Máy bàn và All-in-one”?',ARRAY['Máy bàn thường đặt cố định, có màn hình rời. All-in-one tích hợp phần lớn linh kiện sau màn hình.','Laptop có pin và bàn phím vật lý. Chromebook chạy ChromeOS. Hãy kiểm tra ứng dụng cần dùng có được hỗ trợ.','Cả hai thường có màn hình cảm ứng. Tablet có diện tích thao tác rộng, smartphone thuận tiện liên lạc khi di chuyển.']::text[],'Máy bàn thường đặt cố định, có màn hình rời. All-in-one tích hợp phần lớn linh kiện sau màn hình.','Máy bàn và All-in-one: Máy bàn thường đặt cố định, có màn hình rời. All-in-one tích hợp phần lớn linh kiện sau màn hình.'),
('guide-3-0-concept',3,'Theo bài học, mô tả “Máy bàn thường đặt cố định, có màn hình rời. All-in-one tích hợp phần lớn linh kiện sau màn hình.” liên quan trực tiếp nhất đến khái niệm nào?',ARRAY['Máy bàn và All-in-one','Laptop và Chromebook','Tablet và smartphone']::text[],'Máy bàn và All-in-one','Máy bàn thường đặt cố định, có màn hình rời. All-in-one tích hợp phần lớn linh kiện sau màn hình.'),
('guide-3-1-meaning',3,'Trong bài học, câu nào giải thích phù hợp nhất về “Laptop và Chromebook”?',ARRAY['Laptop có pin và bàn phím vật lý. Chromebook chạy ChromeOS. Hãy kiểm tra ứng dụng cần dùng có được hỗ trợ.','Máy bàn thường đặt cố định, có màn hình rời. All-in-one tích hợp phần lớn linh kiện sau màn hình.','Cả hai thường có màn hình cảm ứng. Tablet có diện tích thao tác rộng, smartphone thuận tiện liên lạc khi di chuyển.']::text[],'Laptop có pin và bàn phím vật lý. Chromebook chạy ChromeOS. Hãy kiểm tra ứng dụng cần dùng có được hỗ trợ.','Laptop và Chromebook: Laptop có pin và bàn phím vật lý. Chromebook chạy ChromeOS. Hãy kiểm tra ứng dụng cần dùng có được hỗ trợ.'),
('guide-3-1-concept',3,'Theo bài học, mô tả “Laptop có pin và bàn phím vật lý. Chromebook chạy ChromeOS. Hãy kiểm tra ứng dụng cần dùng có được hỗ trợ.” liên quan trực tiếp nhất đến khái niệm nào?',ARRAY['Laptop và Chromebook','Máy bàn và All-in-one','Tablet và smartphone']::text[],'Laptop và Chromebook','Laptop có pin và bàn phím vật lý. Chromebook chạy ChromeOS. Hãy kiểm tra ứng dụng cần dùng có được hỗ trợ.'),
('guide-3-2-meaning',3,'Trong bài học, câu nào giải thích phù hợp nhất về “Tablet và smartphone”?',ARRAY['Cả hai thường có màn hình cảm ứng. Tablet có diện tích thao tác rộng, smartphone thuận tiện liên lạc khi di chuyển.','Máy bàn thường đặt cố định, có màn hình rời. All-in-one tích hợp phần lớn linh kiện sau màn hình.','Laptop có pin và bàn phím vật lý. Chromebook chạy ChromeOS. Hãy kiểm tra ứng dụng cần dùng có được hỗ trợ.']::text[],'Cả hai thường có màn hình cảm ứng. Tablet có diện tích thao tác rộng, smartphone thuận tiện liên lạc khi di chuyển.','Tablet và smartphone: Cả hai thường có màn hình cảm ứng. Tablet có diện tích thao tác rộng, smartphone thuận tiện liên lạc khi di chuyển.'),
('guide-3-2-concept',3,'Theo bài học, mô tả “Cả hai thường có màn hình cảm ứng. Tablet có diện tích thao tác rộng, smartphone thuận tiện liên lạc khi di chuyển.” liên quan trực tiếp nhất đến khái niệm nào?',ARRAY['Tablet và smartphone','Máy bàn và All-in-one','Laptop và Chromebook']::text[],'Tablet và smartphone','Cả hai thường có màn hình cảm ứng. Tablet có diện tích thao tác rộng, smartphone thuận tiện liên lạc khi di chuyển.'),
('guide-4-0-meaning',4,'Trong bài học, câu nào giải thích phù hợp nhất về “Viết và trình bày”?',ARRAY['Trình soạn thảo phù hợp với văn bản dài. Trình chiếu tổ chức nội dung thành các trang cho khán giả xem.','Bảng tính đặt dữ liệu trong ô. Công thức giúp tính lại kết quả khi một giá trị thay đổi.','Ứng dụng web thường mở qua trình duyệt. Khi nhiều bạn cùng sửa một tệp, cần đúng quyền chỉnh sửa.']::text[],'Trình soạn thảo phù hợp với văn bản dài. Trình chiếu tổ chức nội dung thành các trang cho khán giả xem.','Viết và trình bày: Trình soạn thảo phù hợp với văn bản dài. Trình chiếu tổ chức nội dung thành các trang cho khán giả xem.'),
('guide-4-0-concept',4,'Theo bài học, mô tả “Trình soạn thảo phù hợp với văn bản dài. Trình chiếu tổ chức nội dung thành các trang cho khán giả xem.” liên quan trực tiếp nhất đến khái niệm nào?',ARRAY['Viết và trình bày','Dữ liệu và công thức','Chạy tại máy hoặc trên web']::text[],'Viết và trình bày','Trình soạn thảo phù hợp với văn bản dài. Trình chiếu tổ chức nội dung thành các trang cho khán giả xem.'),
('guide-4-1-meaning',4,'Trong bài học, câu nào giải thích phù hợp nhất về “Dữ liệu và công thức”?',ARRAY['Bảng tính đặt dữ liệu trong ô. Công thức giúp tính lại kết quả khi một giá trị thay đổi.','Trình soạn thảo phù hợp với văn bản dài. Trình chiếu tổ chức nội dung thành các trang cho khán giả xem.','Ứng dụng web thường mở qua trình duyệt. Khi nhiều bạn cùng sửa một tệp, cần đúng quyền chỉnh sửa.']::text[],'Bảng tính đặt dữ liệu trong ô. Công thức giúp tính lại kết quả khi một giá trị thay đổi.','Dữ liệu và công thức: Bảng tính đặt dữ liệu trong ô. Công thức giúp tính lại kết quả khi một giá trị thay đổi.'),
('guide-4-1-concept',4,'Theo bài học, mô tả “Bảng tính đặt dữ liệu trong ô. Công thức giúp tính lại kết quả khi một giá trị thay đổi.” liên quan trực tiếp nhất đến khái niệm nào?',ARRAY['Dữ liệu và công thức','Viết và trình bày','Chạy tại máy hoặc trên web']::text[],'Dữ liệu và công thức','Bảng tính đặt dữ liệu trong ô. Công thức giúp tính lại kết quả khi một giá trị thay đổi.'),
('guide-4-2-meaning',4,'Trong bài học, câu nào giải thích phù hợp nhất về “Chạy tại máy hoặc trên web”?',ARRAY['Ứng dụng web thường mở qua trình duyệt. Khi nhiều bạn cùng sửa một tệp, cần đúng quyền chỉnh sửa.','Trình soạn thảo phù hợp với văn bản dài. Trình chiếu tổ chức nội dung thành các trang cho khán giả xem.','Bảng tính đặt dữ liệu trong ô. Công thức giúp tính lại kết quả khi một giá trị thay đổi.']::text[],'Ứng dụng web thường mở qua trình duyệt. Khi nhiều bạn cùng sửa một tệp, cần đúng quyền chỉnh sửa.','Chạy tại máy hoặc trên web: Ứng dụng web thường mở qua trình duyệt. Khi nhiều bạn cùng sửa một tệp, cần đúng quyền chỉnh sửa.'),
('guide-4-2-concept',4,'Theo bài học, mô tả “Ứng dụng web thường mở qua trình duyệt. Khi nhiều bạn cùng sửa một tệp, cần đúng quyền chỉnh sửa.” liên quan trực tiếp nhất đến khái niệm nào?',ARRAY['Chạy tại máy hoặc trên web','Viết và trình bày','Dữ liệu và công thức']::text[],'Chạy tại máy hoặc trên web','Ứng dụng web thường mở qua trình duyệt. Khi nhiều bạn cùng sửa một tệp, cần đúng quyền chỉnh sửa.'),
('guide-5-0-meaning',5,'Trong bài học, câu nào giải thích phù hợp nhất về “Cầu nối phần cứng”?',ARRAY['Hệ điều hành quản lý CPU, bộ nhớ và thiết bị. Trình điều khiển giúp hệ điều hành làm việc với thiết bị cụ thể.','Cửa sổ, thanh tác vụ và trình quản lý tệp cho phép chuyển ứng dụng, tìm tài liệu và lưu bài theo thư mục.','Windows, macOS, Linux và các hệ điều hành di động có hệ sinh thái ứng dụng khác nhau. Kiểm tra yêu cầu trước khi cài.']::text[],'Hệ điều hành quản lý CPU, bộ nhớ và thiết bị. Trình điều khiển giúp hệ điều hành làm việc với thiết bị cụ thể.','Cầu nối phần cứng: Hệ điều hành quản lý CPU, bộ nhớ và thiết bị. Trình điều khiển giúp hệ điều hành làm việc với thiết bị cụ thể.'),
('guide-5-0-concept',5,'Theo bài học, mô tả “Hệ điều hành quản lý CPU, bộ nhớ và thiết bị. Trình điều khiển giúp hệ điều hành làm việc với thiết bị cụ thể.” liên quan trực tiếp nhất đến khái niệm nào?',ARRAY['Cầu nối phần cứng','Tổ chức công việc','Tương thích hệ thống']::text[],'Cầu nối phần cứng','Hệ điều hành quản lý CPU, bộ nhớ và thiết bị. Trình điều khiển giúp hệ điều hành làm việc với thiết bị cụ thể.'),
('guide-5-1-meaning',5,'Trong bài học, câu nào giải thích phù hợp nhất về “Tổ chức công việc”?',ARRAY['Cửa sổ, thanh tác vụ và trình quản lý tệp cho phép chuyển ứng dụng, tìm tài liệu và lưu bài theo thư mục.','Hệ điều hành quản lý CPU, bộ nhớ và thiết bị. Trình điều khiển giúp hệ điều hành làm việc với thiết bị cụ thể.','Windows, macOS, Linux và các hệ điều hành di động có hệ sinh thái ứng dụng khác nhau. Kiểm tra yêu cầu trước khi cài.']::text[],'Cửa sổ, thanh tác vụ và trình quản lý tệp cho phép chuyển ứng dụng, tìm tài liệu và lưu bài theo thư mục.','Tổ chức công việc: Cửa sổ, thanh tác vụ và trình quản lý tệp cho phép chuyển ứng dụng, tìm tài liệu và lưu bài theo thư mục.'),
